c(16, "§3.1 table (verbatim); §3.1", "data-caveat", "Prioritised unions (verbatim): " + table("## 3.1 The prioritised picture", 0) + " — 'U:money_harm at 65.71% is the corpus'; app-as-product complaint 26.29%; praise 19.43%.", "n/a", "mixed", "money_harm 115 (65.71%, 1.13★); negative_any 141 (80.57%); trust_collapse 97 (55.43%, 1.07★); paid_evidence 125 (71.43%); consent_failure 56; cancel_friction 51; refund_denied 40 (1.00★); praise_any 34 (4.65★); outcome_any 10 (4.80★)", "none", "table", "generalisable", ["10326285569"], "", "")

c(17, "§3.2 table (verbatim); §3.2", "dont", "Billing and consent — the primary theme (verbatim): " + table("## 3.2 Billing and consent", 0) + " — U:billing_any 93 (53.14%, 1.11★): more than half of every text review reports a billing problem; (b) BILL_NO_CONSENT 36 with a perfect 1.00★ mean ('I purchased the book and did NOT sign up for the app. They charged my card without authorization'; 'yo no he autorizado ningún cobro'; 'Abofalle'); (c) BILL_UNDISCLOSED 26 — 'Why can't you write it loud and clear in the sales order and not hide it in the T&C fine print if you are transparent'; 'hidden in the small print rather than being clearly and prominently disclosed'; (d) BILL_REPEATED 29 ('charged $53/month via Apple Pay, for 9 months'; '$54 every 3 months for an entire year'; 'out over $200'); (e) BILL_SURPRISE_CHARGE 17 + BILL_NO_NOTICE 11 ('if it wasn't for my bank I probably never would have known'); (f) BILL_AFTER_CANCEL 12 ('They confirmed cancellation and a month later they were charging me again'), BILL_AFTER_DELETE 5 ('I deleted my account and the data… but that didn't keep them of billing me through Paypal').", "auto-renewal without consent, notice, or a working stop", "1★-burst", "billing_any 93 / 53.14% / 1.11★; NO_CONSENT 36 / 1.00★; REPEATED 29; UNDISCLOSED 26; SURPRISE 17; AFTER_CANCEL 12; NO_NOTICE 11", "dont", "High-priority", "generalisable", ["12263848892", "12294708869", "12338746489", "13608008284", "12865205440", "14437712673", "13198369428", "13630518203", "11583091379", "13728916762", "13434418762", "13219619467", "12431464017"], "", "")

c(18, "§3.3 table (verbatim); §3.3", "must-have", "Cancellation, refunds and support (verbatim): " + table("## 3.3 Cancellation, refunds", 0) + " — U:cancel_friction 51 (29.14%): the dominant complaint is not that cancelling is slow but that there is no control at all (CANCEL_NO_PATH 27: 'There is no where on the app or the website that tells me how to unsubscribe'; 'not… via your App Store account, their website or from within the app itself'); CANCEL_DARK_PATTERN 2 ('Company uses dark patterns to make it impossible to cancel without contacting customer support. You will forget.'); U:refund_denied 40 (22.86%, every one 1★), 12 shielded by terms ('no refunds as we delivered the service — which is simply not true'; 'they don't issue out refunds unless it's their fault directly'); U:support_fail 36 (20.57%) — SUP_NO_REPLY 14 ('contacted this company FOUR times… not once have they replied'), SUP_CANNED 8 ('Your feedback has been taken into consideration…'), SUP_RESPONSE_FACADE 4 — public developer replies read as PR ('a facade, and for public appeal only… I have no doubt you will paste it below'; 'Addendum to developer response: they're full of it… they've ignored my emails'); the exceptions are informative — SUP_GOOD 2, CANCEL_OK 3: email cancellation works once the right address is found ('fortunately they did this without hassle') — 'the failure is discoverability and routing, not staffing'.", "no cancel control; email-only; refunds refused citing T&Cs; canned public replies", "1★-burst", "cancel_friction 51 / 29.14%; CANCEL_NO_PATH 27 / 15.43%; refund_denied 40 / 1.00★; SUP_NO_REPLY 14 / 8.00%; CANCEL_OK 3; SUP_GOOD 2", "must-have", "High-priority", "generalisable", ["11594706487", "11736211586", "11480357885", "10644767233", "12431814282", "13710291081", "10611003107", "10731982699", "11616551674", "12207701737", "11605113507", "13630518203"], "", "")

c(19, "§3.4 table (verbatim); §3.4", "market", "Payment rails (verbatim): " + table("## 3.4 Payment rails", 0) + " — U:rails_offstore 16 (9.14%) independently confirm the store metadata; seven escalated to the only lever left, blocking the card or closing the account ('Ich habe nun meine Karte sperren lassen'; 'Closing bank account due to this scamming company'; 'Apple thankfully denied all three of their attempts').", "off-store card/PayPal billing", "churn", "rails_offstore 16 / 9.14%; RAIL_BLOCKED_CARD 7 / 4.00%", "product-rule", "High-priority", "generalisable", ["11162929567", "13757151696", "12715520806", "11736211586", "12329827913"], "", "")

c(20, "§3.5 table (verbatim); §3.5", "timeline", "Trust collapse and escalation (verbatim): " + table("## 3.5 Trust collapse", 0) + " — U:trust_collapse 97 (55.43%, 1.07★); TRUST_WARN_OTHERS 67 (38.29%), the largest single code — written to warn the next buyer, not to inform the developer ('read absolutely everything before entering your payment details and check your account afterwards'); TRUST_SCAM_WORD 65 (37.14%) across seven languages (scam, fraud, thieves, Betrug, Abofalle, estafa, timo, engañabobos); TRUST_ESCALATED 16 (FTC, FCC, BBB ×2, UK trading standards, 8 card/PayPal disputes, one class-action call); 'Apple needs to remove them from App Store'; TRUST_CHECKED_REVIEWS 12 — buyers who found the pattern after paying ('I wish I read the reviews first') — the corpus policing itself on the listing where prospects read; one reviewer's first-ever App Store review.", "n/a", "1★-burst", "trust_collapse 97 / 55.43%; WARN_OTHERS 67 / 38.29%; SCAM_WORD 65 / 37.14%; ESCALATED 16 / 9.14%; CHECKED_REVIEWS 12", "none", "High-priority", "generalisable", ["14437712673", "10849098003", "13158666353", "12859046088", "10501320309", "12329827913", "12219957634", "11447285971"], "warning reviews accumulate on the listing and become the conversion gate", "")

c(21, "§3.6 table (verbatim); §3.6", "insight", "The app as a product (verbatim): " + table("## 3.6 The app as a product", 0) + " — too much work for what it returns (APP_COMPLEX 10: 'so overwhelming how much information it gives you to fill in yourself… it would be great to have the app break it down throughout the day and ask you questions… i definitely suffer from choice paralysis'; 'I don't need a full blown psych ward evaluation every single day'); thin for the money (APP_SHALLOW 13, NO_VALUE 14; the recurring comparison is paper — 'Nothing you couldn't do yourself with a piece of paper and pen'; 'the app itself is well designed, but it's basically a glorified tracker and not at all worth the monthly cost'); unattractive (APP_UGLY 9: 'Very old and simple tracking app design'); not as advertised (3: 'The ads made it seem like you could track whatever habits you wanted, but you in fact can not add your own habits'); 14 reviews (8.00%, 1.43★) criticise the app with no money problem — the only pure product signal.", "daily long-form self-assessment; preset habits", "complaint", "app_quality_neg 46 / 26.29%; COMPLEX 10; SHALLOW 13; NO_VALUE 14; UGLY 9; NOT_AS_ADVERTISED 3; pure-product 14 / 1.43★", "none", "High-priority", "generalisable", ["12234895585", "10945514507", "10445166191", "11432265665", "10898288823", "10935045789", "12095515190", "11533637208"], "", "")

c(22, "§3.7 table (verbatim); §3.7", "must-never-break", "Defects (verbatim): " + table("## 3.7 Defects", 0) + " — one theme dominates, the worst possible for a paid product: DEF_LOGIN 14 (8.00%) — people who paid and could not get in ('Unable to even login — Enough said…'; 'we recognise your email adress but the account registration is not complete — you took all the fee in öne min'; 'it says my account doesn't exist when I try to login'; 'it goes straight to a sign in page. It doesn't give you the option to create an account'); DEF_LOCKOUT 2 — deleting your data locks you out of a period you paid for; data overwritten to 'suit some default biorhythms'; 'Forgets your login if you happen to open the app with bad network condition. Requires a restart every day'; no review reports a crash.", "login / account-state failures after payment", "1★-burst", "defect_any 19 / 10.86%; DEF_LOGIN 14 / 8.00% / 1.07★; DEF_LOCKOUT 2; crash 0", "must-never-break", "High-priority", "generalisable", ["11754689227", "11470336869", "11583091379", "12262018303", "12539621585", "11101438874", "11745104386", "11339754455"], "", "")

c(23, "§3.8 table (verbatim); §3.8", "feature", "What people praise (verbatim): " + table("## 3.8 What people praise", 0) + " — U:praise_any 34 (19.43%, 4.65★) but 40% under 60 characters; substantive praise is about structure and content rather than craft: 'great content, fluid and easy to use… now that I can visualize my needs and have a guide'; 'Super adaptable… Très intuitif et motivant'; 'As a developer, the ability to add my own customized trackers is wonderful'; 'customize our own habits based on your actual routine'; 'a clear structure'; PRAISE_COMPANION 3 at 5.00★ — the app working with the book is the only praise code with a perfect score ('I use the app more often than my book because it's more flexible').", "habit tracking, reminders, custom habits, lessons, meditations, book companion", "praise", "praise_any 34 / 19.43% / 4.65★; TRACKING 8; CONTENT 6; EASE 5; CUSTOM 4; REMINDERS 4; COMPANION 3 / 5.00★; PRICE 2", "none", "High-priority", "app-specific", ["13208306937", "13547403147", "13722784232", "10357326014", "11605113507", "10387071772", "10796205051"], "", "")

c(24, "§3.9 table (verbatim); §3.9", "insight", "Outcomes (verbatim): " + table("## 3.9 Outcomes", 0) + " — U:outcome_any 10 (5.71%, 4.80★): 'I went from no morning structure and waking up late, to having some morning routine and waking up early. I haven't had alcohol for over 60 days'; 'at least twice as productive in just around 2 months'; OUT_ABANDONED 5 quit within days ('used it for 4 days and deleted it'); 'Ten reported outcomes against 115 reports of money harm. That ratio is the product problem underneath the billing problem.'", "n/a", "mixed", "outcome_any 10 / 5.71% / 4.80★; ABANDONED 5 / 1.20★", "none", "Very strong", "generalisable", ["10481123302", "10405685383", "11811397305", "12490464361", "10731982699"], "", "")

c(25, "§3.10", "tactic", "Acquisition — how people got here (U:acquisition_any 12, 6.86%): Instagram ads (ACQ_SOCIAL_AD 3: 'Had instagram adverts for this app so I presumed it was safe'; 'ich werde nie wieder auf entsprechende Angebote auf Instagram & co. hereinfallen'); descending prices and manufactured urgency (ACQ_PRESSURE 4: 'they continually advertise and offer at lower and lower prices until you bite'; 'put a LC book in your cart and see how low they will reduce the price if you don't buy right away'; 'fake questions, artificial delays, pseudo customization, pseudo last time offers'); a quiz funnel that never mentions a payment plan (2); a book price gate — the bundle is cheaper than the book alone so the subscription is effectively forced (3: 'they hiked the price of the book if you don't buy a subscription'; the 5★ reviewer describes it neutrally as 'marginally higher'); paid influencers (1); personalisation challenged — 'All they customize is the name on the cover… Pure psycho trick to make you feel invested'; the German translation 'hat eine KI besorgt'.", "Instagram → quiz → book checkout with forced app bundle, descending-price urgency", "1★-burst", "acquisition_any 12 / 6.86% / 1.33★; SOCIAL_AD 3; PRESSURE 4; QUIZ_FUNNEL 2; BOOK_PRICE_GATE 3; INFLUENCER 1; PERSONALISATION_FAKE 2", "dont", "High-priority", "generalisable", ["11404372101", "11411413892", "13729468872", "13613481401", "13711624416", "11339754455", "11018581118", "11149347868", "11605113507", "11616551674"], "", "")

